// Normalize Message: one output item per WhatsApp message in the webhook payload.
// Accepts the full Cloud API webhook body (object / entry / changes / value) or the
// bare `value` object. Status-only updates (delivered / read receipts) produce no items.
const out = [];
for (const item of $input.all()) {
  const raw = item.json || {};
  const value = raw.entry?.[0]?.changes?.[0]?.value ?? raw;
  const messages = Array.isArray(value.messages) ? value.messages : [];
  const contacts = Array.isArray(value.contacts) ? value.contacts : [];
  const phoneNumberId = String(value.metadata?.phone_number_id ?? '');
  for (const m of messages) {
    const contact = contacts.find((c) => c.wa_id === m.from) ?? contacts[0] ?? {};
    const type = String(m.type ?? 'unknown');
    let text = '';
    if (type === 'text') text = m.text?.body ?? '';
    else if (type === 'button') text = m.button?.text ?? '';
    else if (type === 'interactive') text = m.interactive?.button_reply?.title ?? m.interactive?.list_reply?.title ?? '';
    text = String(text).replace(/\s+/g, ' ').trim();
    const ts = Number(m.timestamp);
    const waId = String(m.from ?? '').replace(/\D/g, '');
    out.push({
      json: {
        messageId: String(m.id ?? ''),
        waId,
        phone: waId ? '+' + waId : '',
        name: String(contact.profile?.name ?? '').trim() || 'Customer',
        phoneNumberId,
        type,
        supported: ['text', 'button', 'interactive'].includes(type),
        text,
        receivedAt: Number.isFinite(ts) && ts > 0 ? new Date(ts * 1000).toISOString() : null,
      },
    });
  }
}
return out;

// Detect Language: Arabic or English by counting letters of each script.
// 'und' (undetermined) when the message has no letters at all (emoji, voice note, empty).
const AR = /[؀-ۿݐ-ݿࢠ-ࣿﭐ-﷿ﹰ-﻿]/g;
const LAT = /[A-Za-z]/g;
return $input.all().map((item) => {
  const text = String(item.json.text ?? '');
  const ar = (text.match(AR) || []).length;
  const en = (text.match(LAT) || []).length;
  const language = ar + en === 0 ? 'und' : ar > en ? 'ar' : 'en';
  return { json: { ...item.json, language, scriptCounts: { ar, en } } };
});

// Route Message: deterministic rules that run BEFORE the AI agent.
// route: agent | escalate | reply_only | ignore
// Workflow static data (kept only while the workflow is active) holds duplicate ids,
// a failed-answer counter per customer and a short chat history for handoffs.
const MAX_SEEN = 500;
const MAX_HISTORY = 6;
const FAIL_LIMIT = 2;

const store = $getWorkflowStaticData('global');
store.seenIds = store.seenIds || [];
store.fails = store.fails || {};
store.history = store.history || {};

const normAr = (s) =>
  String(s).replace(/[ً-ٰٟـ]/g, '').replace(/[أإآ]/g, 'ا').replace(/ة/g, 'ه').replace(/ى/g, 'ي');
const arTokens = (norm) =>
  norm.split(/[^؀-ۿa-z0-9-]+/).filter(Boolean).map((t) => t.replace(/^(وال|بال|لل|ال)(?=.{2,})/, ''));
const arHit = (norm, tokens, kw) => (kw.includes(' ') || kw.length >= 4 ? norm.includes(kw) : tokens.includes(kw));

const NOTICE = {
  en: "I'm sorry about this. I've passed your chat to a team member, who will reply here as soon as possible. Please don't send card details in this chat.",
  ar: 'أعتذر عن ذلك. حوّلت محادثتك إلى أحد أعضاء الفريق وسيرد عليك هنا في أقرب وقت. من فضلك لا ترسل بيانات بطاقتك في هذه المحادثة.',
};
NOTICE.und = NOTICE.en + '\n\n' + NOTICE.ar;
const UNSUPPORTED = {
  en: 'I can only read text messages for now. Please type your question and I will help.',
  ar: 'أستطيع قراءة الرسائل النصية فقط حاليًا. من فضلك اكتب سؤالك وسأساعدك.',
};
UNSUPPORTED.und = UNSUPPORTED.en + '\n\n' + UNSUPPORTED.ar;
const UNCLEAR = {
  en: 'Sorry, I did not understand that. Could you write your question in a few words? You can also type "human" to reach a team member.',
  ar: 'عذرًا، لم أفهم رسالتك. هل يمكنك كتابة سؤالك بكلمات قليلة؟ يمكنك أيضًا كتابة "موظف" للتحدث مع أحد أعضاء الفريق.',
};
UNCLEAR.und = UNCLEAR.en + '\n\n' + UNCLEAR.ar;

const STRONG_EN = /\b(scam\w*|fraud\w*|lawyer\w*|sue|chargeback|rip(?:ped)?[- ]?off|steal\w*|stole)\b/i;
const MILD_EN = /\b(worst|terrible|awful|ridiculous|unacceptable|furious|disgusting|useless|angry|fed up|nothing works|waste of (?:my )?money)\b/i;
const STRONG_AR = ['نصب', 'نصاب', 'احتيال', 'حرامي', 'سرقه', 'محامي', 'اقاضي'];
const MILD_AR = ['سيئه جدا', 'خدمه سيئه', 'اسوا', 'اسوء', 'غاضب', 'زفت', 'مهزله', 'غير مقبول', 'مو معقول', 'مش معقول', 'كذابين'];
const HUMAN_EN = /\b(human|real person|live agent|representative|manager|operator)\b|\b(?:talk|speak|chat)\s+(?:to|with)\s+(?:a\s+|an\s+|the\s+)?(?:real\s+|live\s+)?(?:person|human|someone|agent|representative|manager)\b/i;
const HUMAN_AR = ['موظف', 'مدير', 'مسؤول', 'شخص حقيقي', 'انسان', 'بشري'];

const TOPICS = [
  ['refund', /refund|money back|chargeback|cancel/i, ['استرجاع', 'استرداد', 'ارجاع', 'مالي', 'الغاء', 'رد المبلغ']],
  ['certificate', /certificat|diploma/i, ['شهاده', 'شهادات']],
  ['access', /access|log ?in|sign ?in|password|link|download|can'?t open|cannot open|didn'?t (?:get|receive)/i, ['دخول', 'ادخل', 'تسجيل الدخول', 'كلمه المرور', 'رابط', 'تحميل', 'افتح']],
  ['order_status', /\border\b|\bCC-\d{4,6}\b|receipt|invoice|status|tracking|delivery/i, ['طلب', 'طلبي', 'فاتوره', 'ايصال', 'حاله']],
  ['payment', /\bpay|payment|paid|card|paypal|visa|charged|declined/i, ['دفع', 'بطاقه', 'مدفوع']],
  ['pricing', /price|cost|discount|coupon|how much|bundle/i, ['سعر', 'اسعار', 'تكلفه', 'خصم', 'كوبون', 'كم']],
  ['content', /lesson|module|beginner|syllabus|hours|level|learn|language|subtitle|device/i, ['دروس', 'مستوي', 'محتوي', 'ساعات', 'مبتدئ', 'لغه', 'ترجمه', 'جهاز']],
];

function detectTopic(raw, norm, tokens) {
  for (const [topic, re, ar] of TOPICS) {
    if (re.test(raw) || ar.some((k) => arHit(norm, tokens, k))) return topic;
  }
  return 'other';
}

function angerScore(raw, norm) {
  let score = 0;
  if (STRONG_EN.test(raw) || STRONG_AR.some((k) => norm.includes(k))) score += 2;
  if (MILD_EN.test(raw) || MILD_AR.some((k) => norm.includes(k))) score += 1;
  const latin = raw.replace(/[^A-Za-z]/g, '');
  if (latin.length >= 12 && latin.replace(/[^A-Z]/g, '').length / latin.length >= 0.6) score += 1;
  if ((raw.match(/!/g) || []).length >= 3) score += 1;
  return score;
}

function isUnclear(raw) {
  const letters = raw.replace(/[^A-Za-z؀-ۿ]/g, '');
  if (letters.length < 2) return true;
  if (/(.)\1{3,}/.test(raw.replace(/\s/g, ''))) return true;
  if (/[؀-ۿ]/.test(raw)) return false;
  const tokens = raw.match(/[A-Za-z]{3,}/g) || [];
  if (!tokens.length) return false;
  const odd = tokens.filter((t) => !/[aeiouy]/i.test(t) || /[^aeiouy]{5,}/i.test(t)).length;
  return odd / tokens.length >= 0.5;
}

const results = [];
for (const item of $input.all()) {
  const m = item.json;
  const lang = m.language || 'und';
  const raw = String(m.text || '');
  const norm = normAr(raw.toLowerCase());
  const tokens = arTokens(norm);
  const orderMatch = raw.match(/\bCC-\d{4,6}\b/i);
  const out = {
    ...m,
    route: 'agent',
    reason: null,
    reply: '',
    escalate: false,
    outcome: null,
    topic: detectTopic(raw, norm, tokens),
    orderId: orderMatch ? orderMatch[0].toUpperCase() : null,
    sessionKey: m.phone,
  };
  const finish = (route, reason, reply, outcome) => {
    out.route = route;
    out.reason = reason;
    out.reply = reply;
    out.escalate = route === 'escalate';
    out.outcome = outcome;
    out.lastMessages = (store.history[m.phone] || []).slice();
    results.push({ json: out });
  };

  if (!m.waId) { finish('ignore', 'no_sender', '', 'ignored'); continue; }
  if (m.messageId) {
    if (store.seenIds.includes(m.messageId)) { finish('ignore', 'duplicate', '', 'ignored'); continue; }
    store.seenIds.push(m.messageId);
    if (store.seenIds.length > MAX_SEEN) store.seenIds.shift();
  }
  if (!m.supported) { finish('reply_only', 'unsupported_type', UNSUPPORTED[lang], 'reply_only'); continue; }
  if (!raw) { finish('ignore', 'empty', '', 'ignored'); continue; }

  const hist = (store.history[m.phone] = store.history[m.phone] || []);
  hist.push({ from: 'customer', text: raw.slice(0, 300), at: m.receivedAt });
  while (hist.length > MAX_HISTORY) hist.shift();

  const score = angerScore(raw, norm);
  out.angerScore = score;
  if (score >= 2) { finish('escalate', 'unhappy', NOTICE[lang], 'escalated'); continue; }
  if (HUMAN_EN.test(raw) || HUMAN_AR.some((k) => norm.includes(k))) {
    finish('escalate', 'human_requested', NOTICE[lang], 'escalated');
    continue;
  }
  if (isUnclear(raw)) {
    store.fails[m.phone] = (store.fails[m.phone] || 0) + 1;
    if (store.fails[m.phone] >= FAIL_LIMIT) {
      store.fails[m.phone] = 0;
      finish('escalate', 'two_failed_answers', NOTICE[lang], 'escalated');
    } else {
      finish('reply_only', 'unclear', UNCLEAR[lang], 'reply_only');
    }
    continue;
  }
  finish('agent', null, '', null);
}
return results;

// Search FAQ (Code Tool): the agent passes its search words as `query`; the tool returns a string.
// KB is copied from kb/faq.md by tools/build.mjs. Matching is plain keyword scoring, no AI and no vector store.
const KB = [{"id":"access","keywords_en":["access","sign in","log in","login","email","link","receive","received","after paying","after buying","open the course"],"keywords_ar":["دخول","ادخل","اسجل","تسجيل الدخول","رابط","ايميل","بريد","بعد الدفع","بعد الشراء"],"q_en":"How do I access the course after paying?","a_en":"Right after payment we email you a sign-in link from Cedar Course Co. It usually arrives within 10 minutes. Check your spam folder. If nothing arrives after 30 minutes, send me your order number (it looks like CC-1234) and I will check it.","q_ar":"كيف أدخل إلى الدورة بعد الدفع؟","a_ar":"بعد إتمام الدفع نرسل لك بالبريد الإلكتروني رابط تسجيل الدخول من Cedar Course Co. ويصل عادة خلال 10 دقائق. تحقق من مجلد الرسائل غير المرغوبة. إذا لم يصلك شيء بعد 30 دقيقة، أرسل لي رقم طلبك (يشبه CC-1234) وسأتحقق منه."},{"id":"devices","keywords_en":["device","devices","phone","tablet","laptop","computer","app","mobile","browser","watch"],"keywords_ar":["جهاز","اجهزه","جوال","هاتف","تابلت","لابتوب","كمبيوتر","تطبيق","متصفح","اشاهد"],"q_en":"Which devices can I use to watch the lessons?","a_en":"Any phone, tablet or computer with a modern web browser. There is no app to install. Lessons stream online, and the PDF workbooks can be downloaded.","q_ar":"ما الأجهزة التي يمكنني استخدامها لمشاهدة الدروس؟","a_ar":"يمكنك استخدام أي هاتف أو جهاز لوحي أو كمبيوتر فيه متصفح حديث. لا يوجد تطبيق للتثبيت. الدروس تُعرض عبر الإنترنت، ويمكن تنزيل ملفات PDF."},{"id":"lifetime","keywords_en":["lifetime","forever","subscription","monthly","recurring","one-time","one time","expire","expires","updates"],"keywords_ar":["مدى الحياة","دائم","اشتراك","شهري","مره واحده","دفعه واحده","تنتهي","تحديثات"],"q_en":"Is it a one-time payment, and does access expire?","a_en":"Yes, it is a one-time payment. There is no subscription. You keep lifetime access, including future updates to the lessons.","q_ar":"هل الدفع مرة واحدة وهل تنتهي صلاحية الوصول؟","a_ar":"نعم، الدفع مرة واحدة ولا يوجد اشتراك. تحتفظ بالوصول مدى الحياة، بما في ذلك التحديثات القادمة على الدروس."},{"id":"price","keywords_en":["price","prices","cost","how much","discount","coupon","offer","bundle","team","license","student"],"keywords_ar":["سعر","اسعار","تكلفه","كم","خصم","كوبون","عرض","باقه","فريق","ترخيص","طالب"],"q_en":"How much does the course cost, and is there a discount?","a_en":"The course is $89 (USD). The course with the workbook bundle is $129. A team license for 5 seats is $349. We do not run coupon codes at the moment.","q_ar":"كم سعر الدورة وهل يوجد خصم؟","a_ar":"سعر الدورة 89 دولارًا أمريكيًا. الدورة مع حزمة الكتيّب 129 دولارًا. ترخيص الفريق لخمسة مقاعد 349 دولارًا. لا نقدّم كوبونات خصم حاليًا."},{"id":"refund-policy","keywords_en":["refund policy","refund","refunds","money back","return","cancel","guarantee"],"keywords_ar":["سياسه الاسترجاع","استرجاع","استرداد","ارجاع","الغاء","ضمان"],"q_en":"What is your refund policy?","a_en":"You can ask for a full refund within 14 days of buying, for any reason. I can log the request for you; a team member approves it within 2 business days and the money goes back to the original payment method. After 14 days we cannot refund. Team licenses are always reviewed by a person.","q_ar":"ما هي سياسة الاسترجاع لديكم؟","a_ar":"يمكنك طلب استرداد كامل المبلغ خلال 14 يومًا من الشراء ولأي سبب. أستطيع تسجيل الطلب لك، ويوافق عليه أحد أعضاء الفريق خلال يومي عمل، ويعود المبلغ إلى وسيلة الدفع الأصلية. بعد 14 يومًا لا يمكن الاسترداد. تراجع طلبات ترخيص الفريق دائمًا من قبل شخص."},{"id":"certificate","keywords_en":["certificate","certificates","certification","diploma","proof","completion"],"keywords_ar":["شهاده","شهادات","اثبات","اتمام","انهاء"],"q_en":"Do I get a certificate?","a_en":"Yes. When you finish all lessons and pass the final quiz (80% or more), you can download a PDF certificate of completion from your account.","q_ar":"هل أحصل على شهادة؟","a_ar":"نعم. عند إنهاء جميع الدروس واجتياز الاختبار النهائي (80% أو أكثر) يمكنك تنزيل شهادة إتمام بصيغة PDF من حسابك."},{"id":"level","keywords_en":["beginner","beginners","level","experience","prerequisites","requirements","hours","long","modules","syllabus","content","learn"],"keywords_ar":["مبتدئ","مبتدئين","مستوى","خبره","متطلبات","ساعات","مده","وحدات","محتوى","اتعلم"],"q_en":"Is the course suitable for beginners, and how long is it?","a_en":"Yes, it is made for beginners and needs no prior experience. It has 6 modules and about 8 hours of video, plus a PDF workbook for each module.","q_ar":"هل الدورة مناسبة للمبتدئين وكم مدتها؟","a_ar":"نعم، الدورة مصممة للمبتدئين ولا تحتاج إلى خبرة سابقة. تضم 6 وحدات وحوالي 8 ساعات من الفيديو، مع كتيّب PDF لكل وحدة."},{"id":"payment-methods","keywords_en":["payment methods","payment","pay","paypal","visa","mastercard","card","credit card","method","methods","installments"],"keywords_ar":["طرق الدفع","دفع","ادفع","باي بال","فيزا","ماستركارد","بطاقه","تقسيط"],"q_en":"Which payment methods do you accept?","a_en":"We accept Visa, Mastercard and PayPal. Please never send card details in this chat; payment happens only on our secure checkout page. We do not offer installments.","q_ar":"ما طرق الدفع المقبولة؟","a_ar":"نقبل فيزا وماستركارد وباي بال. من فضلك لا ترسل بيانات بطاقتك في هذه المحادثة؛ الدفع يتم فقط عبر صفحة الدفع الآمنة لدينا. لا نقدّم الدفع بالتقسيط."},{"id":"invoice","keywords_en":["invoice","receipt","vat","tax","company","billing","bill"],"keywords_ar":["فاتوره","ايصال","ضريبه","شركه","فواتير"],"q_en":"Can I get an invoice or receipt?","a_en":"A receipt is emailed automatically after payment. For a company invoice with your business name, send me the order number and the name to put on it, and the team will prepare it.","q_ar":"هل يمكنني الحصول على فاتورة أو إيصال؟","a_ar":"يصلك إيصال بالبريد الإلكتروني تلقائيًا بعد الدفع. للحصول على فاتورة باسم شركتك، أرسل لي رقم الطلب والاسم المطلوب وسيجهزها الفريق."},{"id":"support-hours","keywords_en":["support hours","hours","available","availability","contact","weekend","working days","talk","speak","person","reply"],"keywords_ar":["ساعات الدوام","دوام","متاح","دعم","تواصل","عطله","متى","تحدث","شخص","رد"],"q_en":"When can I talk to a person?","a_en":"This chat answers at any time. Team members reply Monday to Friday, 09:00 to 17:00 (UTC). Messages sent outside those hours are answered the next working day.","q_ar":"متى يمكنني التحدث مع شخص؟","a_ar":"هذه المحادثة تجيب في أي وقت. يرد أعضاء الفريق من الاثنين إلى الجمعة من 09:00 إلى 17:00 بالتوقيت العالمي. الرسائل خارج هذه الأوقات يُرد عليها في يوم العمل التالي."},{"id":"language","keywords_en":["arabic","english","language","languages","subtitles","subtitle","translated"],"keywords_ar":["عربي","عربيه","انجليزي","انجليزيه","لغه","ترجمه","ترجمات"],"q_en":"Which language are the lessons in?","a_en":"The lessons are in English with Arabic subtitles. This support chat works in English and Arabic.","q_ar":"بأي لغة الدروس؟","a_ar":"الدروس باللغة الإنجليزية مع ترجمة عربية. وهذه المحادثة تدعم العربية والإنجليزية."}];
const norm = (s) =>
  String(s).toLowerCase().replace(/[ً-ٰٟـ]/g, '').replace(/[أإآ]/g, 'ا').replace(/ة/g, 'ه').replace(/ى/g, 'ي')
    .replace(/[^\p{L}\p{N}\s-]/gu, ' ').replace(/\s+/g, ' ').trim();
const STOP = new Set(['the', 'and', 'for', 'you', 'your', 'are', 'can', 'how', 'what', 'which', 'does', 'this', 'that', 'with', 'have', 'from', 'about', 'please', 'any', 'get', 'got', 'did', 'not', 'its', 'was', 'who', 'where', 'when', 'will', 'would', 'could', 'should', 'there', 'their', 'than', 'then', 'into', 'had', 'has', 'one', 'out', 'just', 'هل', 'ما', 'ماذا', 'كيف', 'في', 'من', 'الي', 'علي', 'عن', 'مع', 'هذا', 'هذه', 'انا', 'لدي', 'ان', 'او', 'لا', 'نعم', 'ثم', 'قد', 'كل', 'قبل', 'هو', 'هي', 'هم', 'لي', 'لك']);
const stem = (t) => (/[؀-ۿ]/.test(t) ? t.replace(/^(وال|بال|لل|ال)(?=.{3,})/, '') : t.length > 4 ? t.replace(/s$/, '') : t);
const tokens = (s) => norm(s).split(' ').filter((t) => t.length >= 3 && !STOP.has(t)).map(stem);

const prepared = KB.map((e) => {
  const kw = [...e.keywords_en, ...e.keywords_ar].map(norm);
  return {
    e,
    kwTokens: new Set(kw.flatMap((k) => tokens(k))),
    phrases: kw.filter((k) => k.includes(' ')),
    qTokens: new Set(tokens(e.q_en + ' ' + e.q_ar)),
  };
});

const nq = norm(query);
const qt = [...new Set(tokens(query))];
const scored = prepared
  .map((p) => {
    let score = 0;
    for (const t of qt) {
      if (p.kwTokens.has(t)) score += 3;
      if (p.qTokens.has(t)) score += 1;
    }
    for (const ph of p.phrases) if (nq.includes(ph)) score += 4;
    return { p, score };
  })
  .sort((a, b) => b.score - a.score);

if (!scored.length || scored[0].score < 3) {
  return 'NO_MATCH: the FAQ has no answer for this. Do not guess. Tell the customer you are not sure and end your reply with [[UNSURE]].';
}
const isAr = /[؀-ۿ]/.test(query);
const picked = scored.filter((s) => s.score >= Math.max(3, scored[0].score * 0.6)).slice(0, 2);
return (
  'FAQ matches. Answer only from these, in the customer\'s language:\n\n' +
  picked.map(({ p: { e } }) => `[${e.id}] Q: ${isAr ? e.q_ar : e.q_en}\nA: ${isAr ? e.a_ar : e.a_en}`).join('\n\n')
);

// Process Agent Reply (Run Once for Each Item): reads the markers the agent was told to use,
//   [[UNSURE]]            it could not answer from the FAQ, order data or policies
//   [[HANDOFF:reason]]    a person must take over
// strips them, counts failed answers, and decides whether to escalate.
const ctx = $('Route Message').last().json;
const store = $getWorkflowStaticData('global');
store.fails = store.fails || {};
store.history = store.history || {};
const lang = ctx.language || 'und';

const NOTICE = {
  en: "I'm sorry about this. I've passed your chat to a team member, who will reply here as soon as possible. Please don't send card details in this chat.",
  ar: 'أعتذر عن ذلك. حوّلت محادثتك إلى أحد أعضاء الفريق وسيرد عليك هنا في أقرب وقت. من فضلك لا ترسل بيانات بطاقتك في هذه المحادثة.',
};
NOTICE.und = NOTICE.en + '\n\n' + NOTICE.ar;
const REPHRASE = {
  en: 'I am not sure about that one, and I do not want to guess. Could you rephrase it, or type "human" to reach a team member?',
  ar: 'لست متأكدًا من ذلك ولا أريد التخمين. هل يمكنك إعادة صياغة سؤالك، أو كتابة "موظف" للتحدث مع أحد أعضاء الفريق؟',
};
REPHRASE.und = REPHRASE.en + '\n\n' + REPHRASE.ar;

const raw = String($input.item.json.output ?? '').trim();
const handoff = raw.match(/\[\[HANDOFF(?::([a-z_]+))?\]\]/i);
const unsure = /\[\[UNSURE\]\]/i.test(raw);
let reply = raw.replace(/\[\[(?:HANDOFF(?::[a-z_]+)?|UNSURE)\]\]/gi, '').trim();

let escalate = false;
let reason = null;
let outcome = 'resolved';
if (handoff) {
  escalate = true;
  reason = handoff[1] ? handoff[1].toLowerCase() : 'agent_handoff';
  outcome = 'escalated';
  store.fails[ctx.phone] = 0;
} else if (unsure || !reply) {
  const n = (store.fails[ctx.phone] || 0) + 1;
  store.fails[ctx.phone] = n;
  if (n >= 2) {
    escalate = true;
    reason = 'two_failed_answers';
    outcome = 'escalated';
    store.fails[ctx.phone] = 0;
  } else {
    outcome = 'unsure';
    reply = REPHRASE[lang];
  }
} else {
  store.fails[ctx.phone] = 0;
}
if (escalate) reply = NOTICE[lang];
reply = reply.slice(0, 900);

const hist = (store.history[ctx.phone] = store.history[ctx.phone] || []);
hist.push({ from: 'bot', text: reply.slice(0, 300), at: new Date().toISOString() });
while (hist.length > 6) hist.shift();

return {
  json: { ...ctx, reply, escalate, reason, outcome, lastMessages: hist.slice() },
};

// Agent Failed (Run Once for Each Item): the AI Agent step gave no answer: the node errored (model down, quota, bad key)
// or came back empty. The customer still gets the honest notice and a person is notified.
const ctx = $('Route Message').last().json;
const lang = ctx.language || 'und';
const NOTICE = {
  en: "I'm sorry about this. I've passed your chat to a team member, who will reply here as soon as possible. Please don't send card details in this chat.",
  ar: 'أعتذر عن ذلك. حوّلت محادثتك إلى أحد أعضاء الفريق وسيرد عليك هنا في أقرب وقت. من فضلك لا ترسل بيانات بطاقتك في هذه المحادثة.',
};
NOTICE.und = NOTICE.en + '\n\n' + NOTICE.ar;
// The error arrives as text (the agent node's own catch), as an object (the error output),
// or not at all (the node stopped before it ran and passed its input through).
const err = $input.item.json.error;
const detail = typeof err === 'string' ? err : err?.message;
return {
  json: {
    ...ctx,
    reply: NOTICE[lang],
    escalate: true,
    reason: 'agent_error',
    outcome: 'escalated',
    agentError: String(detail || 'the agent gave no answer').slice(0, 200),
  },
};

// Capture WhatsApp Reply: stands in for "Send WhatsApp Reply" (WhatsApp Cloud API). Nothing is sent.
// It answers with the same shape a successful send returns, so the nodes after it behave as in the live flow.
const ctx = $('Reply Ready').item.json;
return { json: { messaging_product: 'whatsapp', contacts: [{ input: ctx.waId, wa_id: ctx.waId }], messages: [{ id: 'captured-not-sent' }], capturedSend: { to: ctx.waId, body: ctx.reply } } };

// Capture Sheet Row: stands in for "Log Conversation" (Google Sheets append). Nothing is written.
// `row` has the same columns the live node maps; the other fields are kept so the results file can show them.
const ctx = $('Reply Ready').item.json;
const row = {
  logged_at: $now.toISO(),
  message_id: ctx.messageId,
  customer: '…' + String(ctx.phone).slice(-4),
  language: ctx.language,
  message_type: ctx.type,
  topic: ctx.topic,
  route: ctx.route,
  outcome: ctx.outcome,
  escalation_reason: ctx.reason || '',
  order_id: ctx.orderId || '',
  delivery: $json.error ? 'failed' : ($json.messages ? 'sent' : 'no_reply'),
};
return { json: { row, messageId: ctx.messageId, inbound: ctx.text, reply: ctx.reply, escalate: Boolean(ctx.escalate), capturedSend: $json.capturedSend ?? null } };

// Build Staff Message: the text a team member sees in Slack (or Telegram) for a handoff.
const ctx = $('Reply Ready').item.json;
const p = { phone: ctx.phone, name: ctx.name, language: ctx.language, reason: ctx.reason, topic: ctx.topic, order_id: ctx.orderId || '', lastMessages: ctx.lastMessages };
const LABELS = {
  unhappy: 'Unhappy customer',
  human_requested: 'Customer asked for a person',
  two_failed_answers: 'The bot could not answer twice in a row',
  refund_over_limit: 'Refund above the automatic limit',
  team_task: 'Needs a team member (invoice or account change)',
  payment_dispute: 'Payment problem',
  agent_handoff: 'The agent handed the chat over',
  agent_error: 'The AI step failed',
};
const label = LABELS[p.reason] || p.reason || 'Needs a person';
const langName = p.language === 'ar' ? 'Arabic' : p.language === 'en' ? 'English' : 'unknown';
const msgs = Array.isArray(p.lastMessages) ? p.lastMessages : [];
const lines = msgs.slice(-6).map((m) => `${m.from === 'bot' ? 'Bot' : 'Customer'}: ${String(m.text ?? '').replace(/\s+/g, ' ').slice(0, 300)}`);
const text = [
  `Handoff needed: ${label}`,
  `Customer: ${p.name || 'Unknown'} (${p.phone})`,
  `Language: ${langName} | Topic: ${p.topic || 'n/a'}${p.order_id ? ' | Order: ' + p.order_id : ''}`,
  '',
  'Last messages:',
  ...(lines.length ? lines : ['(none recorded)']),
  '',
  'Reply to the customer in WhatsApp. The bot already told them a person will reply.',
].join('\n');
return { json: { captured: 'team notice (NOT posted to Slack/Telegram)', text: text.slice(0, 3500), reason: p.reason, label } };
